action.code:
assert(!bitmap_full(bitmap, binfo));

#ifdef BITMAP_USE_TREE
	i = binfo->nlevels - 1;
	g = bitmap[binfo->levels[i].group_offset];
	bit = ffs_lu(g);
	while (i > 0) {
		i--;
		g = bitmap[binfo->levels[i].group_offset + bit];
		bit = (bit << LG_BITMAP_GROUP_NBITS) + ffs_lu(g);
	}
#else
	bit = 0;
	for (i = 0; i < binfo->ngroups; i++) {
		if (bitmap[i] != 0) {
			bit = (i << LG_BITMAP_GROUP_NBITS) + ffs_lu(bitmap[i]);
			break;
		}
	}
#endif

atomic_store_u8(&bitmap[bit >> LG_BITMAP_GROUP_NBITS],
    bitmap[bit >> LG_BITMAP_GROUP_NBITS] | (ZU(1) << (bit & BITMAP_GROUP_NBITS_MASK)),
    ATOMIC_ACQ_REL);
return bit;

